head.script:
// https://inswave01.atlassian.net/browse/WAEA-1028



// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > M > removeCellImageSrc]<br/>Body Cell 정보를 사용하여 특정 Body Cell 의 imageSrc 속성값을 제거합니다.",
    "validation" : [
        "Body Cell 의 imageSrc 속성값이 제거되면 Column 의 imageSrc 속성이 적용되어야 합니다.",
        "rowIndex(필수) 파라미터로 imageSrc 속성값을 제거할 Body Cell 의 Row 인덱스를 설정할 수 있어야 합니다.",
        "Row 인덱스는 0 부터 시작하며 GridView 에 표시된 Row 를 기준으로 인덱스가 설정되어야 합니다.",
        "columnInfo(필수) 파라미터로 imageSrc 속성값을 제거할 Body Cell 의 Column 인덱스를 설정할 수 있어야 합니다.",
        "Column 인덱스는 0 부터 시작하며 숨겨진 Column 도 포함하여 인덱스가 설정되어야 합니다.",
        "파라미터에 해당하는 Body Cell 의 imageSrc 속성값 제거 성공 여부를 true/false 로 반환해야 합니다.",
        "파라미터가 유효하지 않으면 false 를 반환해야 합니다.",
        "Body Cell 의 imageSrc 속성값 제거에 성공하면 undefined 값이 설정되어야 합니다.",
        "removeCellImageSrc() 메소드는 Body Cell 의 inputType 속성값에 관계없이 동작해야 합니다.",
        "removeCellImageSrc() 메소드는 Body Cell 의 imageSrc 속성값을 제거하며 Column 단위의 imageSrc 속성값은 제거하지 않아야 합니다."
    ]
}



scwin.onpageload = async function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성 (비동기 dynamicCreate 완료까지 대기)
    await scwin.comp_init();

    // 파라미터 기본 선택값 설정 (정적 select1 은 초기 selectedIndex 미적용)
    par_rowIndex.setSelectedIndex(0);
    par_columnInfo.setSelectedIndex(2);
    par_imageSrc.setSelectedIndex(0);

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성 (Target 재생성 버튼 클릭 시 재실행)
//  - Column 구성(정의 인덱스) : 0 name(text) / 1 hid(textImage+icon, 숨김) / 2 timg(textImage+icon, Column imageSrc 설정) / 3 timg2(textImage+icon, Column imageSrc 미설정)
//    · 인덱스 1 을 setColumnVisible(1, false) 로 숨김 → 숨겨진 Column 도 인덱스에 포함되므로
//      화면상 두번째로 보이는 timg 의 Column 인덱스는 2 가 됨
//    · comp_init 에서 Column 1/2/3 의 모든 Row 에 Body Cell imageSrc 를 미리 설정 → 제거 대상 확보
scwin.comp_init = async function () {
    // 기존 target / dataList 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let strNameSpace = $c.gcm.getNameSpace();
    let grp_comp = $c.gcm.getTestGroup();

    // 안내 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="[전제] Column 구성(인덱스) : 0 = name(text) / 1 = hid(textImage+icon, setColumnVisible 로 숨김) / 2 = timg(textImage+icon, Column imageSrc = /cm/images/base/ico_grid_del.svg 설정) / 3 = timg2(textImage+icon, Column imageSrc 미설정)\n[전제] Target 재생성 시 Column 1 / 2 / 3 의 모든 Row 에 Body Cell imageSrc = /cm/images/base/ico_grid_add.svg 가 setCellImageSrc 로 미리 설정됩니다.\n[절차] rowIndex 와 columnInfo 를 선택하고 removeCellImageSrc 버튼을 클릭하세요. 다시 제거 대상을 만들려면 imageSrc 를 선택하고 setCellImageSrc 버튼을 클릭하세요.\n[확인] 결과창의 반환값 / 제거 후 getCellImageSrc / Cell 이미지 경로 와 그리드 화면의 아이콘 표시를 비교하세요. rowIndex = 99 와 columnInfo = 99 는 유효하지 않은 파라미터 확인용입니다."', '', 'label1');

    // === 바인딩 DataList(dlt_bind) ===
    let strDlt = '';
    strDlt += '<w2:dataList ' + strNameSpace + ' id="dlt_bind" baseNode="list" repeatNode="map">';
    strDlt += '<w2:columnInfo>';
    strDlt += '<w2:column id="name" name="name" dataType="text"></w2:column>';
    strDlt += '<w2:column id="hid" name="hid" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg" name="timg" dataType="text"></w2:column>';
    strDlt += '<w2:column id="timg2" name="timg2" dataType="text"></w2:column>';
    strDlt += '</w2:columnInfo>';
    strDlt += '<w2:data use="true"></w2:data>';
    strDlt += '</w2:dataList>';
    $p.data.create(strDlt);

    let jsonData = [
        { "name": "John", "hid": "H0", "timg": "수정", "timg2": "보기" },
        { "name": "Jane", "hid": "H1", "timg": "수정", "timg2": "보기" },
        { "name": "Mike", "hid": "H2", "timg": "수정", "timg2": "보기" },
        { "name": "Amy",  "hid": "H3", "timg": "수정", "timg2": "보기" }
    ];
    dlt_bind.setJSON(jsonData, false);

    // target 그리드 직접 구성
    let strTarget = '';
    strTarget += '<w2:gridView ' + strNameSpace + ' dataList="data:dlt_bind" id="" style="width:640px;height:220px;">';
    strTarget += '<w2:caption style="" id="caption1" value="removeCellImageSrc test grid"></w2:caption>';
    strTarget += '<w2:header style="" id="header1">';
    strTarget += '<w2:row style="" id="row1">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="hcol1" value="name (0, text)"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="text" id="hcol2" value="hid (1, 숨김)"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="text" id="hcol3" value="timg (2, Column imageSrc 설정)"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="text" id="hcol4" value="timg2 (3, Column imageSrc 미설정)"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:header>';
    strTarget += '<w2:gBody style="" id="gBody1">';
    strTarget += '<w2:row style="" id="row2">';
    strTarget += '<w2:column width="150" style="" inputType="text" id="name" dataList="name"></w2:column>';
    strTarget += '<w2:column width="120" style="" inputType="textImage" viewType="icon" id="hid" dataList="hid"></w2:column>';
    strTarget += '<w2:column width="200" style="" inputType="textImage" viewType="icon" imageSrc="/cm/images/base/ico_grid_del.svg" id="timg" dataList="timg"></w2:column>';
    strTarget += '<w2:column width="*" style="" inputType="textImage" viewType="icon" id="timg2" dataList="timg2"></w2:column>';
    strTarget += '</w2:row>';
    strTarget += '</w2:gBody>';
    strTarget += '</w2:gridView>';

    scwin.target1 = await $p.dynamicCreate(
        "target1",
        "gridView",
        strTarget,
        grp_comp
    );

    // 인덱스 1 (hid) 숨김 → 숨겨진 Column 도 인덱스에 포함됨을 검증
    target1.setColumnVisible(1, false);

    // 제거 대상 확보 : textImage Column(1, 2, 3) 의 모든 Row 에 Body Cell imageSrc 설정
    for (let r = 0; r < 4; r++) {
        target1.setCellImageSrc(r, 1, "/cm/images/base/ico_grid_add.svg");
        target1.setCellImageSrc(r, 2, "/cm/images/base/ico_grid_add.svg");
        target1.setCellImageSrc(r, 3, "/cm/images/base/ico_grid_add.svg");
    }
}



// 반환값을 undefined / ''(Empty String) / 일반 문자열이 구분되도록 표기
scwin.fmtReturn = function (value) {
    if (value === undefined) {
        return "undefined (설정된 값 없음)";
    }
    if (value === null) {
        return "null";
    }
    if (typeof value === "string") {
        return (value === "") ? "'' (Empty String)" : "'" + value + "'";
    }
    return String(value);
}



// Cell 에 실제 표시된 이미지 경로 확인
scwin.getCellImgSrc = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    let imgEl = cellEl.querySelector("img");
    if (!imgEl || !imgEl.getAttribute("src")) {
        return "(이미지 미표시)";
    }
    return imgEl.getAttribute("src");
}



// Cell 에 실제 렌더된 텍스트 확인 (DataList 바인딩 정상 여부)
scwin.getCellText = function (rowIndex, colIndex) {
    let cellEl = document.querySelector("td[id*='target1_cell_" + rowIndex + "_" + colIndex + "']");
    if (!cellEl) {
        return "(Cell 없음)";
    }
    return "'" + cellEl.textContent.trim() + "'";
}



// removeCellImageSrc : 검증 대상 API
scwin.btn_removeCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());

    // 동일 Column 의 다른 Row (Column 단위 imageSrc 유지 확인용)
    let otherRow = (rowIndex === 3) ? 0 : 3;

    let rtn = target1.removeCellImageSrc(rowIndex, columnInfo);

    wf_body_bottom.getObj("scwin").setReturnValue("removeCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("제거 후 getCellImageSrc(" + rowIndex + ", " + columnInfo + ") : " + scwin.fmtReturn(target1.getCellImageSrc(rowIndex, columnInfo)));
    wf_body_bottom.getObj("scwin").setReturnValue("제거 후 Cell 이미지 경로 : " + scwin.getCellImgSrc(rowIndex, columnInfo));
    wf_body_bottom.getObj("scwin").setReturnValue("동일 Column 미제거 Row " + otherRow + " 의 Cell 이미지 경로 : " + scwin.getCellImgSrc(otherRow, columnInfo));
    wf_body_bottom.getObj("scwin").setReturnValue("제거 후 Cell 텍스트 : " + scwin.getCellText(rowIndex, columnInfo));
}



// setCellImageSrc : removeCellImageSrc 의 제거 대상을 다시 만들기 위한 전제 설정용
scwin.btn_setCellImageSrc_onclick = function () {
    let rowIndex = Number(par_rowIndex.getText());
    let columnInfo = Number(par_columnInfo.getText());
    let imageSrc = par_imageSrc.getText();

    let rtn = target1.setCellImageSrc(rowIndex, columnInfo, imageSrc);

    wf_body_bottom.getObj("scwin").setReturnValue("[전제 설정] setCellImageSrc(" + rowIndex + ", " + columnInfo + ", '" + imageSrc + "') : " + rtn);
    wf_body_bottom.getObj("scwin").setReturnValue("[전제 설정] Cell 이미지 경로 : " + scwin.getCellImgSrc(rowIndex, columnInfo));
}
